INSERT INTO peliculas (id,titulo,anio,genero,descripcion,imagen_url,variante,categoria_id) VALUES
  (1,'Minions',2015,'Family','Minions Stuart, Kevin and Bob are recruited by Scarlet Overkill, a super-villain who, alongside her inventor husband Herb, hatches a plot to take over the world.','https://www.themoviedb.org/movie/211672',NULL,9),
  (2,'Interstellar',2014,'Adventure','Interstellar chronicles the adventures of a group of explorers who make use of a newly discovered wormhole to surpass the limitations on human space travel and conquer the vast distances involved in an interstellar voyage.','https://www.themoviedb.org/movie/157336',NULL,9),
  (3,'Deadpool',2016,'Action','Deadpool tells the origin story of former Special Forces operative turned mercenary Wade Wilson, who after being subjected to a rogue experiment that leaves him with accelerated healing powers, adopts the alter ego Deadpool. Armed with his new abilities and a dark, twisted sense of humor, Deadpool hunts down the man who nearly destroyed his life.','https://www.themoviedb.org/movie/293660',NULL,9),
  (4,'Guardians of the Galaxy',2014,'Action','Light years from Earth, 26 years after being abducted, Peter Quill finds himself the prime target of a manhunt after discovering an orb wanted by Ronan the Accuser.','https://www.themoviedb.org/movie/118340',NULL,9),
  (5,'Mad Max: Fury Road',2015,'Action','An apocalyptic story set in the furthest reaches of our planet, in a stark desert landscape where humanity is broken, and most everyone is crazed fighting for the necessities of life. Within this world exist two rebels on the run who just might be able to restore order. There''s Max, a man of action and a man of few words, who seeks peace of mind following the loss of his wife and child in the aftermath of the chaos. And Furiosa, a woman of action and a woman who believes her path to survival may be achieved if she can make it across the desert back to her childhood homeland.','https://www.themoviedb.org/movie/76341',NULL,9),
  (6,'Jurassic World',2015,'Action','Twenty-two years after the events of Jurassic Park, Isla Nublar now features a fully functioning dinosaur theme park, Jurassic World, as originally envisioned by John Hammond.','https://www.themoviedb.org/movie/135397',NULL,9),
  (7,'Pirates of the Caribbean: The Curse of the Black Pearl',2003,'Adventure','Jack Sparrow, a freewheeling 17th-century pirate who roams the Caribbean Sea, butts heads with a rival pirate bent on pillaging the village of Port Royal. When the governor''s daughter is kidnapped, Sparrow decides to help the girl''s love save her. But their seafaring mission is hardly simple.','https://www.themoviedb.org/movie/22',NULL,9),
  (8,'Dawn of the Planet of the Apes',2014,'Science Fiction','A group of scientists in San Francisco struggle to stay alive in the aftermath of a plague that is wiping out humanity, while Caesar tries to maintain dominance over his community of intelligent apes.','https://www.themoviedb.org/movie/119450',NULL,10),
  (9,'The Hunger Games: Mockingjay - Part 1',2014,'Science Fiction','Katniss Everdeen reluctantly becomes the symbol of a mass rebellion against the autocratic Capitol.','https://www.themoviedb.org/movie/131631',NULL,10),
  (10,'Big Hero 6',2014,'Adventure','The special bond that develops between plus-sized inflatable robot Baymax, and prodigy Hiro Hamada, who team up with a group of friends to form a band of high-tech heroes.','https://www.themoviedb.org/movie/177572',NULL,9),
  (11,'Terminator Genisys',2015,'Science Fiction','The year is 2029. John Connor, leader of the resistance continues the war against the machines. At the Los Angeles offensive, John''s fears of the unknown future begin to emerge when TECOM spies reveal a new plot by SkyNet that will attack him from both fronts; past and future, and will ultimately change warfare forever.','https://www.themoviedb.org/movie/87101',NULL,10),
  (12,'Captain America: Civil War',2016,'Adventure','Following the events of Age of Ultron, the collective governments of the world pass an act designed to regulate all superhuman activity. This polarizes opinion amongst the Avengers, causing two factions to side with Iron Man or Captain America, which causes an epic battle between former allies.','https://www.themoviedb.org/movie/271110',NULL,9),
  (13,'Whiplash',2014,'Drama','Under the direction of a ruthless instructor, a talented young drummer begins to pursue perfection at any cost, even his humanity.','https://www.themoviedb.org/movie/244786',NULL,1),
  (14,'The Dark Knight',2008,'Drama','Batman raises the stakes in his war on crime. With the help of Lt. Jim Gordon and District Attorney Harvey Dent, Batman sets out to dismantle the remaining criminal organizations that plague the streets. The partnership proves to be effective, but they soon find themselves prey to a reign of chaos unleashed by a rising criminal mastermind known to the terrified citizens of Gotham as the Joker.','https://www.themoviedb.org/movie/155',NULL,1),
  (15,'The Martian',2015,'Drama','During a manned mission to Mars, Astronaut Mark Watney is presumed dead after a fierce storm and left behind by his crew. But Watney has survived and finds himself stranded and alone on the hostile planet. With only meager supplies, he must draw upon his ingenuity, wit and spirit to subsist and find a way to signal to Earth that he is alive.','https://www.themoviedb.org/movie/286217',NULL,1),
  (16,'Inception',2010,'Action','Cobb, a skilled thief who commits corporate espionage by infiltrating the subconscious of his targets is offered a chance to regain his old life as payment for a task considered to be impossible: "inception", the implantation of another person''s idea into a target''s subconscious.','https://www.themoviedb.org/movie/27205',NULL,9),
  (17,'Frozen',2013,'Animation','Young princess Anna of Arendelle dreams about finding true love at her sister Elsa’s coronation. Fate takes her on a dangerous journey in an attempt to end the eternal winter that has fallen over the kingdom. She''s accompanied by ice delivery man Kristoff, his reindeer Sven, and snowman Olaf. On an adventure where she will find out what friendship, courage, family, and true love really means.','https://www.themoviedb.org/movie/109445',NULL,9),
  (18,'Batman v Superman: Dawn of Justice',2016,'Action','Fearing the actions of a god-like Super Hero left unchecked, Gotham City’s own formidable, forceful vigilante takes on Metropolis’s most revered, modern-day savior, while the world wrestles with what sort of hero it really needs. And with Batman and Superman at war with one another, a new threat quickly arises, putting mankind in greater danger than it’s ever known before.','https://www.themoviedb.org/movie/209112',NULL,9),
  (19,'Avatar',2009,'Action','In the 22nd century, a paraplegic Marine is dispatched to the moon Pandora on a unique mission, but becomes torn between following orders and protecting an alien civilization.','https://www.themoviedb.org/movie/19995',NULL,9),
  (20,'Fight Club',1999,'Drama','A ticking-time-bomb insomniac and a slippery soap salesman channel primal male aggression into a shocking new form of therapy. Their concept catches on, with underground "fight clubs" forming in every town, until an eccentric gets in the way and ignites an out-of-control spiral toward oblivion.','https://www.themoviedb.org/movie/550',NULL,1),
  (21,'Pirates of the Caribbean: Dead Man''s Chest',2006,'Adventure','Captain Jack Sparrow works his way out of a blood debt with the ghostly Davey Jones, he also attempts to avoid eternal damnation.','https://www.themoviedb.org/movie/58',NULL,9),
  (22,'The Imitation Game',2014,'History','Based on the real life story of legendary cryptanalyst Alan Turing, the film portrays the nail-biting race against time by Turing and his brilliant team of code-breakers at Britain''s top-secret Government Code and Cypher School at Bletchley Park, during the darkest days of World War II.','https://www.themoviedb.org/movie/205596',NULL,6),
  (23,'The Avengers',2012,'Science Fiction','When an unexpected enemy emerges and threatens global safety and security, Nick Fury, director of the international peacekeeping agency known as S.H.I.E.L.D., finds himself in need of a team to pull the world back from the brink of disaster. Spanning the globe, a daring recruitment effort begins!','https://www.themoviedb.org/movie/24428',NULL,10),
  (24,'The Godfather',1972,'Drama','Spanning the years 1945 to 1955, a chronicle of the fictional Italian-American Corleone crime family. When organized crime family patriarch, Vito Corleone barely survives an attempt on his life, his youngest son, Michael steps in to take care of the would-be killers, launching a campaign of bloody revenge.','https://www.themoviedb.org/movie/238',NULL,1),
  (25,'Teenage Mutant Ninja Turtles',2014,'Science Fiction','The city needs heroes. Darkness has settled over New York City as Shredder and his evil Foot Clan have an iron grip on everything from the police to the politicians. The future is grim until four unlikely outcast brothers rise from the sewers and discover their destiny as Teenage Mutant Ninja Turtles. The Turtles must work with fearless reporter April and her wise-cracking cameraman Vern Fenwick to save the city and unravel Shredder''s diabolical plan.','https://www.themoviedb.org/movie/98566',NULL,10),
  (26,'Gone Girl',2014,'Mystery','With his wife''s disappearance having become the focus of an intense media circus, a man sees the spotlight turned on him when it''s suspected that he may not be innocent.','https://www.themoviedb.org/movie/210577',NULL,5),
  (27,'Pixels',2015,'Action','Video game experts are recruited by the military to fight 1980s-era video game characters who''ve attacked New York.','https://www.themoviedb.org/movie/257344',NULL,9),
  (28,'Fury',2014,'War','Last months of World War II in April 1945. As the Allies make their final push in the European Theater, a battle-hardened U.S. Army sergeant in the 2nd Armored Division named Wardaddy commands a Sherman tank called "Fury" and its five-man crew on a deadly mission behind enemy lines. Outnumbered and outgunned, Wardaddy and his men face overwhelming odds in their heroic attempts to strike at the heart of Nazi Germany.','https://www.themoviedb.org/movie/228150',NULL,1),
  (29,'X-Men: Apocalypse',2016,'Science Fiction','After the re-emergence of the world''s first mutant, world-destroyer Apocalypse, the X-Men must unite to defeat his extinction level plan.','https://www.themoviedb.org/movie/246655',NULL,10),
  (30,'Pirates of the Caribbean: At World''s End',2007,'Adventure','Captain Barbossa, long believed to be dead, has come back to life and is headed to the edge of the Earth with Will Turner and Elizabeth Swann. But nothing is quite as it seems.','https://www.themoviedb.org/movie/285',NULL,9),
  (31,'Rise of the Planet of the Apes',2011,'Thriller','Scientist Will Rodman is determined to find a cure for Alzheimer''s, the disease which has slowly consumed his father. Will feels certain he is close to a breakthrough and tests his latest serum on apes, noticing dramatic increases in intelligence and brain activity in the primate subjects – especially Caesar, his pet chimpanzee.','https://www.themoviedb.org/movie/61791',NULL,2),
  (32,'Forrest Gump',1994,'Comedy','A man with a low IQ has accomplished great things in his life and been present during significant historic events - in each case, far exceeding what anyone imagined he could do. Yet, despite all the things he has attained, his one true love eludes him. ''Forrest Gump'' is the story of a man who rose above his challenges, and who proved that determination, courage, and love are more important than ability.','https://www.themoviedb.org/movie/13',NULL,8),
  (33,'The Lord of the Rings: The Fellowship of the Ring',2001,'Adventure','Young hobbit Frodo Baggins, after inheriting a mysterious ring from his uncle Bilbo, must leave his home in order to keep it from falling into the hands of its evil creator. Along the way, a fellowship is formed to protect the ringbearer and make sure that the ring arrives at its final destination: Mt. Doom, the only place where it can be destroyed.','https://www.themoviedb.org/movie/120',NULL,9),
  (34,'Despicable Me 2',2013,'Animation','Gru is recruited by the Anti-Villain League to help deal with a powerful new super criminal.','https://www.themoviedb.org/movie/93456',NULL,8),
  (35,'The Shawshank Redemption',1994,'Drama','Framed in the 1940s for the double murder of his wife and her lover, upstanding banker Andy Dufresne begins a new life at the Shawshank prison, where he puts his accounting skills to work for an amoral warden. During his long stretch in prison, Dufresne comes to be admired by the other inmates -- including an older prisoner named Red -- for his integrity and unquenchable sense of hope.','https://www.themoviedb.org/movie/278',NULL,1),
  (36,'Pirates of the Caribbean: On Stranger Tides',2011,'Adventure','Captain Jack Sparrow crosses paths with a woman from his past, and he''s not sure if it''s love -- or if she''s a ruthless con artist who''s using him to find the fabled Fountain of Youth. When she forces him aboard the Queen Anne''s Revenge, the ship of the formidable pirate Blackbeard, Jack finds himself on an unexpected adventure in which he doesn''t know who to fear more: Blackbeard or the woman from his past.','https://www.themoviedb.org/movie/1865',NULL,9),
  (37,'Avengers: Age of Ultron',2015,'Action','When Tony Stark tries to jumpstart a dormant peacekeeping program, things go awry and Earth’s Mightiest Heroes are put to the ultimate test as the fate of the planet hangs in the balance. As the villainous Ultron emerges, it is up to The Avengers to stop him from enacting his terrible plans, and soon uneasy alliances and unexpected action pave the way for an epic and unique global adventure.','https://www.themoviedb.org/movie/99861',NULL,9),
  (38,'Harry Potter and the Chamber of Secrets',2002,'Adventure','Ignoring threats to his life, Harry returns to Hogwarts to investigate – aided by Ron and Hermione – a mysterious series of attacks.','https://www.themoviedb.org/movie/672',NULL,9),
  (39,'The Maze Runner',2014,'Action','Set in a post-apocalyptic world, young Thomas is deposited in a community of boys after his memory is erased, soon learning they''re all trapped in a maze that will require him to join forces with fellow "runners" for a shot at escape.','https://www.themoviedb.org/movie/198663',NULL,9),
  (40,'Tomorrowland',2015,'Adventure','Bound by a shared destiny, a bright, optimistic teen bursting with scientific curiosity and a former boy-genius inventor jaded by disillusionment embark on a danger-filled mission to unearth the secrets of an enigmatic place somewhere in time and space that exists in their collective memory as "Tomorrowland."','https://www.themoviedb.org/movie/158852',NULL,9),
  (41,'Inside Out',2015,'Drama','Growing up can be a bumpy road, and it''s no exception for Riley, who is uprooted from her Midwest life when her father starts a new job in San Francisco. Like all of us, Riley is guided by her emotions - Joy, Fear, Anger, Disgust and Sadness. The emotions live in Headquarters, the control center inside Riley''s mind, where they help advise her through everyday life. As Riley and her emotions struggle to adjust to a new life in San Francisco, turmoil ensues in Headquarters. Although Joy, Riley''s main and most important emotion, tries to keep things positive, the emotions conflict on how best to navigate a new city, house and school.','https://www.themoviedb.org/movie/150540',NULL,1),
  (42,'One Flew Over the Cuckoo''s Nest',1975,'Drama','While serving time for insanity at a state mental hospital, implacable rabble-rouser, Randle Patrick McMurphy inspires his fellow patients to rebel against the authoritarian rule of head nurse, Mildred Ratched.','https://www.themoviedb.org/movie/510',NULL,1),
  (43,'The Hunger Games: Mockingjay - Part 2',2015,'Action','With the nation of Panem in a full scale war, Katniss confronts President Snow in the final showdown. Teamed with a group of her closest friends – including Gale, Finnick, and Peeta – Katniss goes off on a mission with the unit from District 13 as they risk their lives to stage an assassination attempt on President Snow who has become increasingly obsessed with destroying her. The mortal traps, enemies, and moral choices that await Katniss will challenge her more than any arena she faced in The Hunger Games.','https://www.themoviedb.org/movie/131634',NULL,9),
  (44,'Twilight',2008,'Adventure','When Bella Swan moves to a small town in the Pacific Northwest to live with her father, she starts school and meets the reclusive Edward Cullen, a mysterious classmate who reveals himself to be a 108-year-old vampire. Despite Edward''s repeated cautions, Bella can''t help but fall in love with him, a fatal move that endangers her own life when a coven of bloodsuckers try to challenge the Cullen clan.','https://www.themoviedb.org/movie/8966',NULL,9),
  (45,'Star Wars',1977,'Adventure','Princess Leia is captured and held hostage by the evil Imperial forces in their effort to take over the galactic Empire. Venturesome Luke Skywalker and dashing captain Han Solo team together with the loveable robot duo R2-D2 and C-3PO to rescue the beautiful princess and restore peace and justice in the Empire.','https://www.themoviedb.org/movie/11',NULL,9),
  (46,'Brave',2012,'Animation','Brave is set in the mystical Scottish Highlands, where Mérida is the princess of a kingdom ruled by King Fergus and Queen Elinor. An unruly daughter and an accomplished archer, Mérida one day defies a sacred custom of the land and inadvertently brings turmoil to the kingdom. In an attempt to set things right, Mérida seeks out an eccentric old Wise Woman and is granted an ill-fated wish. Also figuring into Mérida’s quest — and serving as comic relief — are the kingdom’s three lords: the enormous Lord MacGuffin, the surly Lord Macintosh, and the disagreeable Lord Dingwall.','https://www.themoviedb.org/movie/62177',NULL,9),
  (47,'The Lord of the Rings: The Return of the King',2003,'Adventure','Aragorn is revealed as the heir to the ancient kings as he, Gandalf and the other members of the broken fellowship struggle to save Gondor from Sauron''s forces. Meanwhile, Frodo and Sam bring the ring closer to the heart of Mordor, the dark lord''s realm.','https://www.themoviedb.org/movie/122',NULL,9),
  (48,'Pulp Fiction',1994,'Thriller','A burger-loving hit man, his philosophical partner, a drug-addled gangster''s moll and a washed-up boxer converge in this sprawling, comedic crime caper. Their adventures unfurl in three stories that ingeniously trip back and forth in time.','https://www.themoviedb.org/movie/680',NULL,2),
  (49,'The Hobbit: The Battle of the Five Armies',2014,'Action','Immediately after the events of The Desolation of Smaug, Bilbo and the dwarves try to defend Erebor''s mountain of treasure from others who claim it: the men of the ruined Laketown and the elves of Mirkwood. Meanwhile an army of Orcs led by Azog the Defiler is marching on Erebor, fueled by the rise of the dark lord Sauron. Dwarves, elves and men must unite, and the hope for Middle-Earth falls into Bilbo''s hands.','https://www.themoviedb.org/movie/122917',NULL,9),
  (50,'Iron Man',2008,'Action','After being held captive in an Afghan cave, billionaire engineer Tony Stark creates a unique weaponized suit of armor to fight evil.','https://www.themoviedb.org/movie/1726',NULL,9),
  (51,'Ant-Man',2015,'Science Fiction','Armed with the astonishing ability to shrink in scale but increase in strength, master thief Scott Lang must embrace his inner-hero and help his mentor, Doctor Hank Pym, protect the secret behind his spectacular Ant-Man suit from a new generation of towering threats. Against seemingly insurmountable obstacles, Pym and Lang must plan and pull off a heist that will save the world.','https://www.themoviedb.org/movie/102899',NULL,10),
  (52,'Spirited Away',2001,'Fantasy','A ten year old girl who wanders away from her parents along a path that leads to a world ruled by strange and unusual monster-like animals. Her parents have been changed into pigs along with others inside a bathhouse full of these creatures. Will she ever see the world how it once was?','https://www.themoviedb.org/movie/129',NULL,9),
  (53,'X-Men: Days of Future Past',2014,'Action','The ultimate X-Men ensemble fights a war for the survival of the species across two time periods as they join forces with their younger selves in an epic battle that must change the past – to save our future.','https://www.themoviedb.org/movie/127585',NULL,9),
  (54,'Transformers: Age of Extinction',2014,'Science Fiction','As humanity picks up the pieces, following the conclusion of "Transformers: Dark of the Moon," Autobots and Decepticons have all but vanished from the face of the planet. However, a group of powerful, ingenious businessman and scientists attempt to learn from past Transformer incursions and push the boundaries of technology beyond what they can control - all while an ancient, powerful Transformer menace sets Earth in his cross-hairs.','https://www.themoviedb.org/movie/91314',NULL,10),
  (55,'Chappie',2015,'Crime','Every child comes into the world full of promise, and none more so than Chappie: he is gifted, special, a prodigy. Like any child, Chappie will come under the influence of his surroundings—some good, some bad—and he will rely on his heart and soul to find his way in the world and become his own man. But there''s one thing that makes Chappie different from any one else: he is a robot.','https://www.themoviedb.org/movie/198184',NULL,4),
  (56,'Spider-Man 3',2007,'Fantasy','The seemingly invincible Spider-Man goes up against an all-new crop of villain – including the shape-shifting Sandman. While Spider-Man’s superpowers are altered by an alien organism, his alter ego, Peter Parker, deals with nemesis Eddie Brock and also gets caught up in a love triangle.','https://www.themoviedb.org/movie/559',NULL,9),
  (57,'Night at the Museum: Secret of the Tomb',2014,'Adventure','When the magic powers of The Tablet of Ahkmenrah begin to die out, Larry Daley (Ben Stiller) spans the globe, uniting favorite and new characters while embarking on an epic quest to save the magic before it is gone forever.','https://www.themoviedb.org/movie/181533',NULL,9),
  (58,'Lucy',2014,'Action','A woman, accidentally caught in a dark deal, turns the tables on her captors and transforms into a merciless warrior evolved beyond human logic.','https://www.themoviedb.org/movie/240832',NULL,9),
  (59,'Batman Begins',2005,'Action','Driven by tragedy, billionaire Bruce Wayne dedicates his life to uncovering and defeating the corruption that plagues his home, Gotham City.  Unable to work within the system, he instead creates a new identity, a symbol of fear for the criminal underworld - The Batman.','https://www.themoviedb.org/movie/272',NULL,9),
  (60,'Mission: Impossible - Rogue Nation',2015,'Action','Ethan and team take on their most impossible mission yet, eradicating the Syndicate - an International rogue organization as highly skilled as they are, committed to destroying the IMF.','https://www.themoviedb.org/movie/177677',NULL,9),
  (61,'Despicable Me',2010,'Animation','Villainous Gru lives up to his reputation as a despicable, deplorable and downright unlikable guy when he hatches a plan to steal the moon from the sky. But he has a tough time staying on task after three orphans land in his care.','https://www.themoviedb.org/movie/20352',NULL,1),
  (62,'Maze Runner: The Scorch Trials',2015,'Action','Thomas and his fellow Gladers face their greatest challenge yet: searching for clues about the mysterious and powerful organization known as WCKD. Their journey takes them to the Scorch, a desolate landscape filled with unimaginable obstacles. Teaming up with resistance fighters, the Gladers take on WCKD’s vastly superior forces and uncover its shocking plans for them all.','https://www.themoviedb.org/movie/294254',NULL,9),
  (63,'The Dark Knight Rises',2012,'Action','Following the death of District Attorney Harvey Dent, Batman assumes responsibility for Dent''s crimes to protect the late attorney''s reputation and is subsequently hunted by the Gotham City Police Department. Eight years later, Batman encounters the mysterious Selina Kyle and the villainous Bane, a new terrorist leader who overwhelms Gotham''s finest. The Dark Knight resurfaces to protect a city that has branded him an enemy.','https://www.themoviedb.org/movie/49026',NULL,9),
  (64,'Maleficent',2014,'Fantasy','The untold story of Disney''s most iconic villain from the 1959 classic ''Sleeping Beauty''. A beautiful, pure-hearted young woman, Maleficent has an idyllic life growing up in a peaceable forest kingdom, until one day when an invading army threatens the harmony of the land.  Maleficent rises to be the land''s fiercest protector, but she ultimately suffers a ruthless betrayal – an act that begins to turn her heart into stone. Bent on revenge, Maleficent faces an epic battle with the invading King''s successor and, as a result, places a curse upon his newborn infant Aurora. As the child grows, Maleficent realizes that Aurora holds the key to peace in the kingdom - and to Maleficent''s true happiness as well.','https://www.themoviedb.org/movie/102651',NULL,9),
  (65,'Gravity',2013,'Science Fiction','Dr. Ryan Stone, a brilliant medical engineer on her first Shuttle mission, with veteran astronaut Matt Kowalsky in command of his last flight before retiring. But on a seemingly routine spacewalk, disaster strikes. The Shuttle is destroyed, leaving Stone and Kowalsky completely alone-tethered to nothing but each other and spiraling out into the blackness of space. The deafening silence tells them they have lost any link to Earth and any chance for rescue. As fear turns to panic, every gulp of air eats away at what little oxygen is left. But the only way home may be to go further out into the terrifying expanse of space.','https://www.themoviedb.org/movie/49047',NULL,10),
  (66,'Harry Potter and the Philosopher''s Stone',2001,'Adventure','Harry Potter has lived under the stairs at his aunt and uncle''s house his whole life. But on his 11th birthday, he learns he''s a powerful wizard -- with a place waiting for him at the Hogwarts School of Witchcraft and Wizardry. As he learns to harness his newfound powers with the help of the school''s kindly headmaster, Harry uncovers the truth about his parents'' deaths -- and about the villain who''s to blame.','https://www.themoviedb.org/movie/671',NULL,9),
  (67,'Bruce Almighty',2003,'Fantasy','Bruce Nolan toils as a "human interest" television reporter in Buffalo, N.Y. Despite his high ratings and the love of his beautiful girlfriend, Grace, Bruce remains unfulfilled. At the end of the worst day in his life, he angrily ridicules God -- and the Almighty responds, endowing Bruce with all of His divine powers.','https://www.themoviedb.org/movie/310',NULL,8),
  (68,'The Fifth Element',1997,'Adventure','In 2257, a taxi driver is unintentionally given the task of saving a young girl who is part of the key that will ensure the survival of humanity.','https://www.themoviedb.org/movie/18',NULL,9),
  (69,'The Hobbit: An Unexpected Journey',2012,'Adventure','Bilbo Baggins, a hobbit enjoying his quiet life, is swept into an epic quest by Gandalf the Grey and thirteen dwarves who seek to reclaim their mountain home from Smaug, the dragon.','https://www.themoviedb.org/movie/49051',NULL,9),
  (70,'Quantum of Solace',2008,'Adventure','Quantum of Solace continues the adventures of James Bond after Casino Royale. Betrayed by Vesper, the woman he loved, 007 fights the urge to make his latest mission personal. Pursuing his determination to uncover the truth, Bond and M interrogate Mr. White, who reveals that the organization that blackmailed Vesper is far more complex and dangerous than anyone had imagined.','https://www.themoviedb.org/movie/10764',NULL,9),
  (71,'Spectre',2015,'Action','A cryptic message from Bond’s past sends him on a trail to uncover a sinister organization. While M battles political forces to keep the secret service alive, Bond peels back the layers of deceit to reveal the terrible truth behind SPECTRE.','https://www.themoviedb.org/movie/206647',NULL,9),
  (72,'The Twilight Saga: Eclipse',2010,'Adventure','Bella once again finds herself surrounded by danger as Seattle is ravaged by a string of mysterious killings and a malicious vampire continues her quest for revenge. In the midst of it all, she is forced to choose between her love for Edward and her friendship with Jacob, knowing that her decision has the potential to ignite the ageless struggle between vampire and werewolf. With her graduation quickly approaching, Bella is confronted with the most important decision of her life.','https://www.themoviedb.org/movie/24021',NULL,9),
